mapper.insert:

  SELECT ('AD' || TO_CHAR(SYSDATE,'YYYYMMDD') || TRIM(TO_CHAR(SQ_DIS_AD.NEXTVAL, '000000'))) AS APD_SEQ  FROM DUAL

/* NewChangeMspWriteMapper.insertDisPrmtApd */
  INSERT INTO MSP_DIS_APD (
  APD_SEQ
  ,REGST_DT
  ,PROC_YN
  ,RES_NO

    ,REQUEST_KEY


    ,CONTRACT_NUM


    ,PRMT_ID

  ,CHNL_CD
  ,EVNT_CD
  ,ENGG_MNTH_CNT
  ,OPEN_AGNT_CD
  ,PRMT_AGNT_CD
  ,RATE_CD
  ,ON_OFF_TYPE
  ,OPER_TYPE
  ,REQ_BUY_TYPE
  ,REGST_ID
  ,REGST_DTTM
) VALUES(
  #{apdSeq}
  ,TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS')
  ,'N'
  ,#{resNo}

    ,#{requestKey}


    ,#{contractNum}


    ,#{prmtId}

  ,'01'
  ,#{evntCd}
  ,'00'
  ,#{cntpntShopId}
  ,#{prmtAgntCd}
  ,#{socCode}
  ,#{onOffType}
  ,#{operType}
  ,#{reqBuyType}


        ,#{cretId}


        ,'MCP'


  ,SYSDATE
)
